coding.starterCode:
SELECT country
FROM users
ORDER BY country;

coding.referenceSolution:
SELECT DISTINCT country
FROM users
ORDER BY country;

mcq.snippet:
CREATE TABLE products(name TEXT, price REAL);
INSERT INTO products VALUES ('Pen', 2), ('Desk', 120), ('Lamp', 35);
SELECT name FROM products WHERE price > 10 ORDER BY price DESC LIMIT 1;

CREATE TABLE users(name TEXT, country TEXT);
INSERT INTO users VALUES ('A','IN'), ('B','US'), ('C','IN'), ('D','UK');
SELECT DISTINCT country FROM users;

CREATE TABLE p(name TEXT, price REAL);
INSERT INTO p VALUES ('B', 5), ('A', 1), ('C', 9);
SELECT name FROM p ORDER BY price;

coding.starterCode:
SELECT name, phone
FROM contacts
ORDER BY id;

coding.referenceSolution:
SELECT name, COALESCE(phone, 'n/a') AS phone
FROM contacts
ORDER BY id;

mcq.snippet:
CREATE TABLE p(name TEXT, category TEXT, price REAL);
INSERT INTO p VALUES ('a','books',50), ('b','games',50), ('c','games',10);
SELECT name FROM p WHERE category = 'books' OR category = 'games' AND price < 30;

CREATE TABLE t(id INTEGER);
INSERT INTO t VALUES (1),(2),(3),(4),(5),(6);
SELECT id FROM t ORDER BY id LIMIT 2 OFFSET 2;

coding.starterCode:
SELECT name, category, price
FROM products
ORDER BY category, price;

coding.referenceSolution:
SELECT name, category, price
FROM products
ORDER BY category, price DESC;

coding.starterCode:
SELECT first || ' ' || last AS full_name
FROM people
ORDER BY id;

coding.referenceSolution:
SELECT first || COALESCE(' ' || last, '') AS full_name
FROM people
ORDER BY id;

