coding.starterCode:
DELETE FROM users
WHERE id NOT IN (SELECT MAX(id) FROM users GROUP BY email);
SELECT id, email FROM users ORDER BY id;

coding.referenceSolution:
DELETE FROM users
WHERE id NOT IN (SELECT MIN(id) FROM users GROUP BY email);
SELECT id, email FROM users ORDER BY id;

coding.starterCode:
SELECT name, total_stars / votes AS avg_rating
FROM ratings
ORDER BY id;

coding.referenceSolution:
SELECT name, total_stars * 1.0 / NULLIF(votes, 0) AS avg_rating
FROM ratings
ORDER BY id;

